#include <stdio.h>
#include <stdlib.h>

#define MAXV 8
#define QUEUE_SIZE MAXV

int main(int argc, char *argv[])
{
    /* Input validation: need even number of numeric arguments */
    if ((argc - 1) % 2 != 0) {
        puts("INVALID_INPUT");
        return 1;
    }

    int adj[MAXV][MAXV] = {{0}};

    for (int i = 1; i + 1 < argc; i += 2) {
        char *endptr;
        long u = strtol(argv[i], &endptr, 10);
        if (*endptr != '\0' || u < 0 || u >= MAXV) {
            puts("INVALID_INPUT");
            return 1;
        }
        long v = strtol(argv[i + 1], &endptr, 10);
        if (*endptr != '\0' || v < 0 || v >= MAXV) {
            puts("INVALID_INPUT");
            return 1;
        }
        adj[u][v] = 1;
        adj[v][u] = 1; // undirected graph
    }

    int visited[MAXV] = {0};
    int component_index = 0;

    for (int start = 0; start < MAXV; ++start) {
        if (visited[start])
            continue;

        int q[QUEUE_SIZE];
        int q_head = 0, q_tail = 0;
        int comp_vertices[MAXV];
        int comp_cnt = 0;

        visited[start] = 1;
        q[q_tail++] = start;

        while (q_head < q_tail) {
            int v = q[q_head++];
            comp_vertices[comp_cnt++] = v;
            for (int nb = 0; nb < MAXV; ++nb) {
                if (adj[v][nb] && !visited[nb]) {
                    visited[nb] = 1;
                    q[q_tail++] = nb;
                }
            }
        }

        printf("%d: {", component_index);
        for (int i = 0; i < comp_cnt; ++i) {
            printf("%d", comp_vertices[i]);
            if (i + 1 < comp_cnt)
                putchar(',');
        }
        putchar('}');
        putchar('\n');
        ++component_index;
    }

    return 0;
}
